    correction=json.loads((HERE/'hair-west-workbench.json').read_text()) if (HERE/'hair-west-workbench.json').is_file() else None
    write('manifest.json',{'status':'Direction-gated review prototype, not production activation','authorization':'Owner delegated recommended PixelLab decisions and continued the existing work. Closed six-call chain ceiling38 announced before paid calls, no automatic retries or USD overage; global auto unchanged. Main543c92a preserved, including collaborator maps/Albatross changes.','jobs':jobs,'generation_usage':{'this_chain_confirmed':usage,'chain_ceiling':38,'prior_confirmed':109,'prior_tool_reported':2,'prior_failed_job_unexposed_estimate':1,'cumulative_confirmed':109+usage,'cumulative_conservative':112+usage},'exact_workbench_edit':correction,'scope':{'source_frames':'Two independently generated eight-step profiles plus echoed references kept separate','existing_art':'Four-view Idle, front/back Walk and four original swords reused','rig':[84,84],'pivot':[42,65],'native_body':[64,64],'crop':[16,0,48,64],'native_layer_cell':[32,64],'layer_atlas':[256,64],'body_padding':[10,10],'layer_padding':[26,10],'seed_for_related_inpaint_calls':607822274,'production_enabled':False,'original_raw_outputs_preserved':True,'weapon_depth':'Per-action/per-direction: profile Walk uses near-hand foreground80; old Idle depths unchanged','rejected_composition_study':'body-west-grip.gif preserves the initial behind-body depth diagnostic; do not register it as final art'},'coverage':pack['coverage'],'missing':['Walk/'+d for d in ['south','north','west','east'] if d not in pack['coverage']['walk']]+['Attack/sword four directions and other class action categories','Full-character artistic approval, including cross-view proportions and hairstyle continuity'],'sha256':{p.name:digest(p) for p in HERE.glob('*.png') if 'inspection' not in p.name},'gif_sha256':{p.name:digest(p) for p in HERE.glob('*.gif')},'report':'../../docs/PAPER-DOLL-CAMINHADAS-LATERAIS.md'})
    recipe=[{'_pixellab':{'paid_call_policy':'explicit_user_run_request_required','output_directory':'pixellab-pip-generations/paper-doll-walk-profiles-20261021','output_collision_policy':'create_unique'},'_comment_prompt':'Prossiga','TASK':'Verify current explicit run authority, authenticated MCP access and the38-generation ceiling before paid calls. Create a unique empty folder. Copy the original native left/right Idle sources and references byte-for-byte. Preserve previous art, main and collaborator changes. Generation prompts were composed from the requested modular character contract.'}]
    for job in jobs:
        recipe.append({'MCP '+job['tool'].removeprefix('MCP '):job['parameters']})
        recipe.append({'TASK':'Poll this exact job to terminal status without resubmission. Download and preserve every original. For a body, verify the echoed reference and retain the eight generated poses in order; inspect motion, facing, canvas, proportions and hand grips before dependent layers. Build native32x64 source cells only by reversible transparent-margin crop, original per-frame masks, and320x64 style context; no resizing or local repainting. For a layer, audit all eight cells and protected pixels, then inspect actual artwork before accepting a direction.'})
        if job.get('job_id')=='7cc73a52-1319-4cc3-a91d-5df7ceda4cda' and correction:
            recipe.append({'TASK':'Inspect the original hair atlas in PixelLab Workbench. Two isolated pixels in cells4/7 were found. Keep the original raw/gallery asset. On a NEW copy, apply the following exact guarded erasures; the initial wrong colour guard failed without changes, then the observed second colour was used.'})
            recipe.append({'MCP pixelart_workbench':correction['parameters']})
            recipe.append({'TASK':'Download the new native PNG. Verify that ONLY118/20 and214/20 became transparent and every other decoded RGBA value is identical. Preserve both originals and the exact edit record; no palette, body, pose or frame-order changes. Tool describes this operation as free for subscribers; per-call usage is not exposed.'})
    recipe.append({'TASK':'Compose only complete direction-gated layers into rig84/pivot42/65 with measured integer hand sockets and original direction-specific swords. Keep all pieces approved:false and all missing actions atomic fallback. Produce native sheets and exact-palette transparent looping GIFs without quantization, mirror, duplicate poses or temporal trimming. If the combined palette exceeds255 colours omit its GIF, keeping native per-direction GIFs. Validate independent original-source RGBA, all poses/layer toggles, depth, sockets, world movement/combat, Haki, Zoan, caches and saves. Build Pages; push the exclusive branch and open a PR without merge.'})
    write('profiles.blueprint.json',recipe);print('Charged:',usage,'conservative cumulative:',112+usage,'coverage:',pack['coverage']['walk'])
